it("distinguishes an uncommitted artifact from an inconclusive Git observation", () => {
  const state = (overrides: Record<string, unknown>) => ({
    path: "deliverables/package.md",
    present: true,
    tracked: true,
    committed: false,
    digest: "a".repeat(64),
    source: "WORKTREE" as const,
    commit: null,
    detail: "tracked with uncommitted changes",
    ...overrides,
  });
  const warningFor = (overrides: Record<string, unknown>) =>
    episodeArtifactWarnings([state(overrides)]).join(" ");

  expect(warningFor({})).toMatch(/uncommitted changes/iu);

  for (const detail of [
    "HEAD changed during artifact observation",
    "HEAD could not be verified",
    "artifact blob could not be read at observed HEAD",
  ]) {
    const warning = warningFor({ detail });
    expect(warning).toContain(detail);
    expect(warning).toMatch(/observation problem/iu);
    expect(warning).not.toMatch(/uncommitted/iu);
  }

  expect(warningFor({ present: false, tracked: false, source: "ABSENT", digest: null, detail: "not found" })).toMatch(/was not found/iu);
  expect(warningFor({ tracked: false, detail: "not tracked by Git" })).toMatch(/not tracked by Git/iu);
  expect(warningFor({ committed: true, source: "RESULT_COMMIT", commit: "b".repeat(40) })).toBe("");
});

