function isArtifactObservationIssue(detail: string): boolean {
  const normalized = detail.toLowerCase();
  return (
    normalized.includes("head changed") ||
    normalized.includes("head moved") ||
    normalized.includes("head could not be verified") ||
    normalized.includes("head could not be confirmed") ||
    normalized.includes("blob could not be read") ||
    normalized.includes("artifact could not be read")
  );
}

